Sorry, yes, this is the script I've been using:
```lua

dlg = Dialog()
  :entry   { label="Label 1:" }
  :tab     { id="tab1", text="Tab 1", onclick=function (ev)
                                        dlg:modify{id="tab2", enabled=true}
                                      end  }
    :check   { text="Some checkbox" }
    :button  { text="Press me"}
  :tab     { id="tab2", text="Tab 2", onclick=function (ev)
                                        dlg:modify{id="tab2", enabled=false}
                                      end }
    :entry   { label="Label 2:" }
  :endtabs { selected="tab2", id="MyTabs", onchange=function (ev)
                                             print("selected tab: " .. ev.tab)
                                           end}
  :entry   { label="Label 3:" }
  :check   { text="Another checkbox" }
  :tab     { text="Main data" }
    :entry   { id="name", label="Name" }
    :entry   { label="Last name"}
  :tab     { text="Secondary", id="persontab2" }
    :entry   { label="Job:" }
    :entry   { label="Address:" }
  :endtabs { selected="tab2", id="Person"}
  :button  { id="done", text="Done"}

dlg:show{autoscrollbars=true}

if dlg.data.done then
  app.alert("MyTabs seleced tab: '" .. dlg.data.MyTabs .. "', Person selected tab: '" .. dlg.data.Person .. "'")
end
```

By the way, the selected="tab2" in the Person tabs is on purpose to see that it doesn't crash when specifying an inexistent tab id, and also that it doesn't mix tabs ids from different tab widgets.
